package com.mcnex.conversation;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;
public class HelpSpeedProbe extends Instrumentation {
 private JSONObject report=new JSONObject();private JSONArray results=new JSONArray(),loads=new JSONArray();
 private final String[] names={"HDR 도움","양자화 도움","도움 불필요 판단"};
 private final String[] contexts={"역광에서 사람 얼굴이 어둡게 나오는 카메라 문제를 검토하고 있습니다. HDR을 적용하면 밝은 배경과 얼굴을 함께 개선할 수 있을까요?","휴대폰에서 AI 모델을 실행하기 위해 INT4 양자화를 적용하고 NPU 사용을 검토하고 있습니다. 양자화가 모델의 메모리와 정확도에 어떤 영향을 주나요?","오늘 점심은 회사 식당에서 먹었고 오후에는 동료와 산책했습니다. 내일도 비가 오지 않으면 같이 산책하려고 합니다."};
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void save()throws Exception{report.put("samples",results).put("loads",loads);try(FileOutputStream out=getTargetContext().openFileOutput("help-speed.json",0)){out.write(report.toString().getBytes("UTF-8"));}}
 public void onStart(){try{String[] order={"Gemma GPU","EXAONE OpenCL GPU","EXAONE OpenCL GPU","Gemma GPU"};File files=getTargetContext().getFilesDir();for(int block=0;block<order.length;block++){String model=order[block];Bundle progress=new Bundle();progress.putString("stage",(block+1)+"/4 "+model);sendStatus(1,progress);long begin=SystemClock.elapsedRealtime();AiEngine engine=model.startsWith("Gemma")?new LiteAi(new File(files,"model.litertlm"),getTargetContext().getCacheDir()):new LocalAi(new File(files,"model.gguf"),true);long loaded=SystemClock.elapsedRealtime();loads.put(new JSONObject().put("block",block).put("model",model).put("loadMs",loaded-begin));try{for(int i=0;i<contexts.length;i++){long start=SystemClock.elapsedRealtime();String raw=engine.explain(contexts[i],"자동 대화 도움","assist");long elapsed=SystemClock.elapsedRealtime()-start;JSONObject item=new JSONObject().put("block",block).put("model",model).put("case",names[i]).put("generateMs",elapsed).put("characters",raw.length()).put("raw",raw);try{JSONObject help=new JSONObject(raw.substring(raw.indexOf('{'),raw.lastIndexOf('}')+1));boolean valid=help.optString("kind").matches("none|term|reply")&&(help.optString("kind").equals("none")||!help.optString("text").isEmpty());item.put("validJson",valid).put("help",help);}catch(Exception parse){item.put("validJson",false);}results.put(item);save();}}finally{engine.close();}}report.put("ok",true);save();}catch(Exception|LinkageError e){try{report.put("ok",false).put("error",e.toString());save();}catch(Exception ignored){}}Bundle b=new Bundle();b.putString("reportFile","help-speed.json");b.putInt("samples",results.length());finish(report.optBoolean("ok")?-1:0,b);}
}
